/**
 * The decorative layer, drawn here rather than generated by a model.
 *
 * ── Why this module exists ──
 * The gap between what this add-in produces and what the good AI deck tools
 * produce is not layout and it is not colour — those are solved. It is TEXTURE:
 * paper grain, a rule that looks drawn rather than ruled, a wash of colour
 * behind a heading. Every skill that has those gets them by asking an image
 * model to paint the whole slide, which costs an API key, costs seconds per
 * page, and costs the thing that matters most here — the result is a
 * photograph of a slide, so changing one word means regenerating the page.
 *
 * SVG gets to the same place from the other direction. A noise filter is paper.
 * A line with a few points nudged off true is a hand-drawn line. A gradient is
 * a wash. All of it is arithmetic, it runs in the task pane with no network and
 * no key, and PowerPoint will turn any of it back into editable shapes with
 * right-click → 轉換為圖形.
 *
 * ── One SVG per slide, not one per ornament ──
 * Every insert is a separate `setSelectedDataAsync` round trip, and a slide
 * wanting paper plus a frame plus a rule would pay for three. So the whole
 * decorative layer is composed into a single document and goes in once, before
 * any shape is drawn — which is also what puts it underneath them, since
 * setSelectedDataAsync appends and PowerPoint z-orders by insertion.
 *
 * ── Deterministic, deliberately ──
 * The wobble comes from a seeded generator rather than Math.random. Two runs of
 * the same deck have to look the same: a person who regenerates slide 4 and
 * finds its frame has moved will not think 「手繪風」, they will think the tool
 * is unreliable. It also makes every line of this testable.
 */

/** 16:9 at the same scale the rest of the host uses. */
const W = 960;
const H = 540;

/**
 * A small deterministic generator.
 *
 * Numerical Recipes' LCG constants. Nothing here needs statistical quality —
 * it needs to produce the same sequence twice.
 */
function rng(seed) {
  let s = (Math.abs(Math.floor(seed)) % 2147483647) || 42;
  return () => {
    s = (s * 1103515245 + 12345) % 2147483648;
    return s / 2147483648;
  };
}

/** A stable seed from a string, so one look always wobbles the same way. */
function seedOf(str) {
  let h = 2166136261;
  for (let i = 0; i < String(str).length; i++) {
    h ^= String(str).charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h);
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const n2 = (v) => Math.round(Number(v) * 100) / 100;

/**
 * A line that looks drawn.
 *
 * ── How it works, and why it is not a filter ──
 * The obvious approach is an SVG turbulence displacement on a straight line.
 * That renders beautifully in a browser and unpredictably in PowerPoint, whose
 * SVG support covers shapes and gradients far better than it covers filter
 * primitives — and an ornament that vanishes on half the machines is worse than
 * no ornament.
 *
 * So the wobble is in the GEOMETRY: the line is cut into segments and each
 * joint is nudged off true by a fraction of the stroke weight. It is a plain
 * path, it converts to an editable freeform, and it renders the same everywhere.
 *
 * Two passes, slightly apart, because a single stroke reads as a bad straight
 * line while two read as a pen that went over it twice.
 */
export function handLine(x1, y1, x2, y2, opts = {}) {
  const colour = opts.color || '#333333';
  const weight = Number(opts.weight) || 2;
  const amp = opts.amp === undefined ? weight * 0.9 : Number(opts.amp);
  const steps = Math.max(3, Math.min(24, Math.round(Math.hypot(x2 - x1, y2 - y1) / 34)));
  const passes = opts.passes === undefined ? 2 : Number(opts.passes);
  const rand = rng(opts.seed === undefined ? seedOf(`${x1},${y1},${x2},${y2}`) : opts.seed);

  const out = [];
  for (let p = 0; p < passes; p++) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      // The ends stay put. A hand-drawn line wanders in the middle and lands
      // where it was aiming — one that misses its own endpoint reads as broken.
      const slack = Math.sin(t * Math.PI);
      const dx = (rand() - 0.5) * amp * slack;
      const dy = (rand() - 0.5) * amp * slack;
      pts.push(`${n2(x1 + (x2 - x1) * t + dx)},${n2(y1 + (y2 - y1) * t + dy)}`);
    }
    out.push(`<polyline points="${pts.join(' ')}" fill="none" stroke="${esc(colour)}"`
      + ` stroke-width="${n2(weight)}" stroke-linecap="round" stroke-linejoin="round"`
      + ` opacity="${p === 0 ? 1 : 0.55}"/>`);
  }
  return out.join('');
}

/** Four hand-drawn lines. Corners overshoot slightly, the way a pen does. */
export function handFrame(x, y, w, h, opts = {}) {
  const o = Number(opts.overshoot === undefined ? 5 : opts.overshoot);
  const seed = opts.seed === undefined ? seedOf(`frame${x}${y}${w}${h}`) : Number(opts.seed);
  return [
    handLine(x - o, y, x + w + o, y, { ...opts, seed: seed + 1 }),
    handLine(x + w, y - o, x + w, y + h + o, { ...opts, seed: seed + 2 }),
    handLine(x + w + o, y + h, x - o, y + h, { ...opts, seed: seed + 3 }),
    handLine(x, y + h + o, x, y - o, { ...opts, seed: seed + 4 }),
  ].join('');
}

/**
 * Paper.
 *
 * feTurbulence IS used here, unlike in handLine, because there is no geometric
 * substitute for grain and because the failure mode is benign: a renderer that
 * ignores the filter shows a flat tinted rectangle, which is exactly what the
 * untextured looks use anyway. The ornament degrades to the default rather than
 * to nothing.
 */
export function paper(fill, opts = {}) {
  const id = `g${opts.id || 'p'}`;
  const grain = opts.grain === undefined ? 0.09 : Number(opts.grain);
  return `<defs><filter id="${id}" x="0" y="0" width="100%" height="100%">`
    + `<feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="3" seed="7"/>`
    + `<feColorMatrix type="saturate" values="0"/>`
    + `</filter></defs>`
    + `<rect width="${W}" height="${H}" fill="${esc(fill)}"/>`
    + `<rect width="${W}" height="${H}" filter="url(#${id})" opacity="${n2(grain)}"/>`;
}

/** A soft diagonal wash. Two stops, low contrast — a third reads as a gradient
 *  effect from 2007 rather than as a ground. */
export function wash(from, to, opts = {}) {
  const id = `w${opts.id || 'a'}`;
  return `<defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1">`
    + `<stop offset="0" stop-color="${esc(from)}"/>`
    + `<stop offset="1" stop-color="${esc(to)}"/>`
    + `</linearGradient></defs>`
    + `<rect width="${W}" height="${H}" fill="url(#${id})"/>`;
}

/** A faint dot grid. The dashboard look's ground — it says "measured" without
 *  putting a single line anywhere the content has to avoid. */
export function dotGrid(fill, dot, opts = {}) {
  const id = `d${opts.id || 'a'}`;
  const step = Number(opts.step) || 24;
  return `<defs><pattern id="${id}" width="${step}" height="${step}"`
    + ` patternUnits="userSpaceOnUse">`
    + `<circle cx="1" cy="1" r="1" fill="${esc(dot)}" opacity="0.55"/>`
    + `</pattern></defs>`
    + `<rect width="${W}" height="${H}" fill="${esc(fill)}"/>`
    + `<rect width="${W}" height="${H}" fill="url(#${id})"/>`;
}

/**
 * Motifs — the quiet geometry that runs across every page of a deck.
 *
 * ── What this is for, in the words that produced it ──
 * 「我每頁都可以有類似白底加波浪、菱形幾何的背景圖，但它不會喧賓奪主，就很像 PPT
 * 模板那樣每頁都有這個背景，而我們的圖表、文字放在這背景上。」
 *
 * That is exactly what a bought template gives people, and exactly what was
 * missing here. Note what it is NOT: it is not a picture of the subject. A
 * template's background is abstract on purpose, which is why the same one works
 * on page 2 and page 14 and never looks irrelevant.
 *
 * ── Why this beats generating a background image, on every axis ──
 *   consistency  the same marks in the same places on every page, which is the
 *                entire source of the 「模板感」 — a different generated image per
 *                page reads as a collage, not a deck
 *   cost         arithmetic, so it is free and instant; a generated background
 *                is fifteen to sixty seconds a page against one GPU
 *   relevance    abstract geometry is never off-topic, so it cannot produce the
 *                「這張圖跟內容有什麼關係」 reaction
 *   editable     right-click → 轉換為圖形 and every wave is a real shape
 *
 * ── The one rule they all obey ──
 * Nothing crosses the content band at full strength. The marks live in the
 * margins, the corners and the bottom, at an opacity where you notice the page
 * has been designed without noticing what is on it. A motif you can read is a
 * motif that is competing with the slide.
 */
const MOTIF_ALPHA = 0.1;

/** Soft bands along the foot of the page. The friendliest of the set. */
function mWaves(tone, accent) {
  const out = [];
  for (let i = 0; i < 3; i++) {
    const y = H - 40 + i * 26;
    const amp = 26 - i * 5;
    const d = `M -20 ${n2(y)} `
      + `C ${n2(W * 0.2)} ${n2(y - amp)}, ${n2(W * 0.32)} ${n2(y + amp)}, ${n2(W * 0.5)} ${n2(y)} `
      + `S ${n2(W * 0.82)} ${n2(y - amp)}, ${n2(W + 20)} ${n2(y - amp * 0.4)} `
      + `L ${n2(W + 20)} ${n2(H + 40)} L -20 ${n2(H + 40)} Z`;
    out.push(`<path d="${d}" fill="${esc(i === 1 ? accent : tone)}"`
      + ` opacity="${n2(MOTIF_ALPHA * (i === 1 ? 0.7 : 1))}"/>`);
  }
  return out.join('');
}

/** Outlined diamonds, clustered where the content is not. */
function mDiamonds(tone, accent) {
  const rand = rng(31);
  const out = [];
  // Two clusters, top-right and bottom-left: the two corners a slide layout
  // leaves empty most often.
  for (const [cx, cy, n] of [[W - 120, 92, 7], [96, H - 96, 5]]) {
    for (let i = 0; i < n; i++) {
      const size = 16 + rand() * 46;
      const x = cx + (rand() - 0.5) * 300;
      const y = cy + (rand() - 0.5) * 170;
      const pts = [[x, y - size], [x + size, y], [x, y + size], [x - size, y]]
        .map((q) => q.map(n2).join(',')).join(' ');
      const solid = i % 3 === 0;
      out.push(`<polygon points="${pts}" fill="${solid ? esc(accent) : 'none'}"`
        + ` stroke="${esc(tone)}" stroke-width="1.2"`
        + ` opacity="${n2(MOTIF_ALPHA * (solid ? 0.8 : 1.3))}"/>`);
    }
  }
  return out.join('');
}

/** Concentric arcs sweeping out of one corner. */
function mArcs(tone, accent) {
  const out = [];
  for (let i = 0; i < 6; i++) {
    const r = 150 + i * 78;
    out.push(`<circle cx="${n2(W + 60)}" cy="${n2(-40)}" r="${n2(r)}" fill="none"`
      + ` stroke="${esc(i === 2 ? accent : tone)}" stroke-width="${i === 2 ? 2.4 : 1.2}"`
      + ` opacity="${n2(MOTIF_ALPHA * 1.4)}"/>`);
  }
  return out.join('');
}

/** A faint ruled grid. The most neutral motif, and the one for data-heavy decks. */
function mGrid(tone) {
  return `<defs><pattern id="mg" width="48" height="48" patternUnits="userSpaceOnUse">`
    + `<path d="M48 0 L0 0 0 48" fill="none" stroke="${esc(tone)}" stroke-width="0.8"/>`
    + `</pattern></defs>`
    + `<rect width="${W}" height="${H}" fill="url(#mg)" opacity="${n2(MOTIF_ALPHA * 0.9)}"/>`;
}

/** Contour lines, like a map. Quietly technical without being a grid. */
function mTopo(tone, accent) {
  const rand = rng(77);
  const out = [];
  for (let i = 0; i < 7; i++) {
    const y = 110 + i * 62;
    const pts = [];
    for (let x = -20; x <= W + 20; x += 60) {
      pts.push(`${n2(x)},${n2(y + Math.sin((x / W) * Math.PI * 2 + i) * (22 + rand() * 10))}`);
    }
    out.push(`<polyline points="${pts.join(' ')}" fill="none"`
      + ` stroke="${esc(i === 3 ? accent : tone)}" stroke-width="1.1"`
      + ` opacity="${n2(MOTIF_ALPHA * 1.2)}"/>`);
  }
  return out.join('');
}

/** A diagonal band across one corner. The most graphic of the set. */
function mRibbon(tone, accent) {
  return `<polygon points="${W - 300},0 ${W},0 ${W},${H} ${W - 120},${H}"`
    + ` fill="${esc(tone)}" opacity="${n2(MOTIF_ALPHA)}"/>`
    + `<polygon points="${W - 150},0 ${W - 60},0 ${W},${H} ${W - 90},${H}"`
    + ` fill="${esc(accent)}" opacity="${n2(MOTIF_ALPHA * 0.8)}"/>`;
}

/** A single wedge in one corner. Almost nothing, which is sometimes right. */
function mCorner(tone, accent) {
  return `<polygon points="0,${H} 0,${H - 220} 300,${H}"`
    + ` fill="${esc(tone)}" opacity="${n2(MOTIF_ALPHA)}"/>`
    + `<polygon points="0,${H} 0,${H - 96} 130,${H}"`
    + ` fill="${esc(accent)}" opacity="${n2(MOTIF_ALPHA * 0.9)}"/>`;
}

const MOTIF = {
  waves: mWaves,
  diamonds: mDiamonds,
  arcs: mArcs,
  grid: (t) => mGrid(t),
  topo: mTopo,
  ribbon: mRibbon,
  corner: mCorner,
};

export const MOTIF_NAMES = Object.keys(MOTIF);

/**
 * The whole decorative layer for one slide, or null when the look wants none.
 *
 * `spec` carries only what changes the ornament: the look's texture and stroke
 * settings, the resolved palette, and whether the slide has a title (a rule
 * belonging to a title that is not there is just a mark).
 */
export function ornamentSvg(spec = {}) {
  const { texture, strokes } = spec;
  const motif = MOTIF[String(spec.motif || '').toLowerCase()];
  if (!texture && strokes !== 'hand' && !motif) return null;

  const th = spec.theme || {};
  const parts = [];

  if (texture === 'paper') parts.push(paper(spec.ground || th.ground || '#FFFFFF', { id: 'a' }));
  else if (texture === 'wash') parts.push(wash(spec.ground || th.ground || '#FFFFFF', th.tint || '#F2F2F2', { id: 'a' }));
  else if (texture === 'dots') parts.push(dotGrid(spec.ground || th.ground || '#FFFFFF', th.line || '#DDDDDD', { id: 'a' }));
  // No texture, but the ornament still owns the page: the flat ground has to be
  // painted here or the motif lands on whatever PowerPoint's layout provides.
  else parts.push(`<rect width="${W}" height="${H}" fill="${esc(spec.ground || '#FFFFFF')}"/>`);

  /**
   * Under the frame and the rules, over the ground.
   *
   * The order matters: a motif drawn after a hand-drawn frame would sit on top
   * of it, and the frame is content in a way the motif is not.
   */
  if (motif) {
    parts.push(motif(spec.tone || th.strong || '#888888', spec.accent || th.accent || '#888888'));
  }

  if (strokes === 'hand') {
    const ink = spec.ink || th.strong || '#333333';
    const accent = th.accent || ink;
    if (spec.frame !== false) {
      parts.push(handFrame(26, 26, W - 52, H - 52,
        { color: ink, weight: 1.6, amp: 2.4, seed: 101 }));
    }
    if (spec.title) {
      // Under the title, the width of the fixed rule the other looks draw — the
      // ornament changes how it is made, not where it sits.
      const y = 93 + (Number(spec.topPad) || 0);
      parts.push(handLine(38, y, 146, y, { color: accent, weight: 3.4, amp: 2.6, seed: 202 }));
    }
    if (spec.footband) {
      parts.push(handLine(38, 486, W - 38, 486, { color: ink, weight: 1.4, amp: 1.8, seed: 303 }));
    }
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"`
    + ` viewBox="0 0 ${W} ${H}">${parts.join('')}</svg>`;
}
